22	const DEFAULT_MAX_ALLOC: u64 = 128 * 1024 * 1024; // 128 MB
23	const ENABLE_LIBJPEG_ENV: &str = "DYN_MM_ENABLE_LIBJPEG";
24	// CI-only guard: an enabled JPEG test must exercise TurboJPEG, never its fallback.
25	const REQUIRE_LIBJPEG_TURBO_TEST_ENV: &str = "DYNAMO_REQUIRE_LIBJPEG_TURBO_TEST";
26	static LIBJPEG_TURBO_UNAVAILABLE_WARNING: Once = Once::new();
