39	/// Image decoder limits - can only be set via server config, not runtime kwargs.
40	#[derive(Clone, Debug, Serialize, Deserialize, ToSchema)]
41	#[serde(deny_unknown_fields)]
42	pub struct ImageDecoderLimits {
43	    #[serde(default)]
44	    pub max_image_width: Option<u32>,
45	    #[serde(default)]
46	    pub max_image_height: Option<u32>,
47	    /// Maximum allowed total allocation of the decoder in bytes
48	    #[serde(default)]
49	    pub max_alloc: Option<u64>,
50	}
51	
52	impl Default for ImageDecoderLimits {
53	    fn default() -> Self {
54	        Self {
55	            max_image_width: None,
56	            max_image_height: None,
57	            max_alloc: Some(DEFAULT_MAX_ALLOC),
58	        }
59	    }
60	}
61	
62	impl ImageDecoderLimits {
63	    fn validate_output(&self, width: u32, height: u32, channels: usize) -> Result<usize> {
64	        if self.max_image_width.is_some_and(|limit| width > limit)
65	            || self.max_image_height.is_some_and(|limit| height > limit)
66	        {
67	            anyhow::bail!("Image dimensions exceed configured limits: {width}x{height}");
68	        }
69	
70	        let nbytes = u64::from(width)
71	            .checked_mul(u64::from(height))
72	            .and_then(|pixels| pixels.checked_mul(channels as u64))
73	            .ok_or_else(|| {
74	                anyhow::anyhow!("Image allocation size overflow for dimensions: {width}x{height}")
75	            })?;
76	        if let Some(limit) = self.max_alloc
77	            && nbytes > limit
78	        {
79	            anyhow::bail!("Image allocation {nbytes} bytes exceeds configured limit {limit} bytes");
80	        }
81	        usize::try_from(nbytes)
82	            .map_err(|_| anyhow::anyhow!("Image allocation does not fit in usize: {nbytes} bytes"))
83	    }
84	}
