119	impl Decoder for ImageDecoder {
120	    fn with_runtime(&self, runtime: Option<&Self>) -> Self {
121	        match runtime {
122	            Some(r) => {
123	                let mut d = r.clone();
124	                d.limits.clone_from(&self.limits);
125	                d.enable_libjpeg = self.enable_libjpeg;
126	                d
127	            }
128	            None => self.clone(),
129	        }
130	    }
131	
132	    fn decode(&self, data: EncodedMediaData) -> Result<DecodedMediaData> {
133	        let bytes = data.into_bytes()?;
134	        self.warn_if_libjpeg_unavailable();
135	
136	        let format = image::guess_format(&bytes)?;
137	        let request = ImageDecodeRequest {
138	            bytes: &bytes,
139	            format,
140	            limits: &self.limits,
141	        };
142	        let turbojpeg = turbojpeg_backend();
143	        let image_reader = image_reader_backend();
144	        let image = if self.enable_libjpeg && turbojpeg.supports(format) {
145	            match turbojpeg.try_decode(request)? {
146	                ImageDecodeOutcome::Decoded(image) => image,
147	                ImageDecodeOutcome::NotHandled(reason) => {
148	                    ensure_fallback_allowed(
149	                        turbojpeg.name(),
150	                        reason,
151	                        std::env::var_os(REQUIRE_LIBJPEG_TURBO_TEST_ENV).is_some(),
152	                    )?;
153	                    decode_required_backend(image_reader, request)?
154	                }
155	            }
156	        } else {
157	            decode_required_backend(image_reader, request)?
158	        };
159	
160	        decoded_image_to_media_data(image)
161	    }
162	}
163	
164	fn ensure_fallback_allowed(
165	    backend: &str,
166	    reason: BackendDecline,
167	    backend_required: bool,
168	) -> Result<()> {
169	    if backend_required {
170	        anyhow::bail!(
171	            "{backend} was required by {REQUIRE_LIBJPEG_TURBO_TEST_ENV}, but the input would have \
172	             fallen back to image::ImageReader: {reason}"
173	        );
174	    }
175	    Ok(())
176	}
177	
178	fn decode_required_backend(
179	    backend: &dyn ImageDecodeBackend,
180	    request: ImageDecodeRequest<'_>,
181	) -> Result<DecodedImage> {
182	    match backend.try_decode(request)? {
183	        ImageDecodeOutcome::Decoded(image) => Ok(image),
184	        ImageDecodeOutcome::NotHandled(reason) => {
185	            anyhow::bail!("{} did not handle the input: {reason}", backend.name())
186	        }
187	    }
188	}
189	
190	fn decoded_image_to_media_data(image: DecodedImage) -> Result<DecodedMediaData> {
191	    let channels = image.pixel_format.channels();
192	    let color_type = image.pixel_format.color_type();
193	    let shape = (image.height as usize, image.width as usize, channels);
194	    let array = Array3::from_shape_vec(shape, image.pixels)?;
195	    let mut decoded: DecodedMediaData = array.try_into()?;
196	    decoded.tensor_info.metadata = Some(DecodedMediaMetadata::Image(ImageMetadata {
197	        format: Some(image.source_format),
198	        color_type,
199	        layout: ImageLayout::HWC,
200	    }));
201	    Ok(decoded)
202	}
