204	impl ImageDecoder {
205	    #[doc(hidden)]
206	    pub fn with_libjpeg_for_benchmark(mut self, enabled: bool) -> Self {
207	        self.enable_libjpeg = enabled;
208	        self
209	    }
210	
211	    pub(crate) fn warn_if_libjpeg_unavailable(&self) {
212	        if self.enable_libjpeg
213	            && turbojpeg_backend().availability() == BackendAvailability::Unavailable
214	        {
215	            LIBJPEG_TURBO_UNAVAILABLE_WARNING.call_once(|| {
216	                if std::env::var_os(REQUIRE_LIBJPEG_TURBO_TEST_ENV).is_some() {
217	                    tracing::warn!(
218	                        "libjpeg-turbo image decoding is required by \
219	                         {REQUIRE_LIBJPEG_TURBO_TEST_ENV}, but libturbojpeg could not be loaded; \
220	                         JPEG requests will fail"
221	                    );
222	                } else {
223	                    tracing::warn!(
224	                        "libjpeg-turbo image decoding is enabled, but libturbojpeg could not be \
225	                         loaded; falling back to image::ImageReader for JPEG inputs"
226	                    );
227	                }
228	            });
229	        }
230	    }
231	}
