249	    fn create_test_image(
250	        width: u32,
251	        height: u32,
252	        channels: u32,
253	        format: image::ImageFormat,
254	    ) -> Vec<u8> {
255	        // Create dynamic image based on number of channels with constant values
256	        let pixels = vec![128u8; channels as usize].repeat((width * height) as usize);
257	        let dynamic_image = match channels {
258	            1 => DynamicImage::ImageLuma8(
259	                ImageBuffer::from_vec(width, height, pixels).expect("Failed to create image"),
260	            ),
261	            3 => DynamicImage::ImageRgb8(
262	                ImageBuffer::from_vec(width, height, pixels).expect("Failed to create image"),
263	            ),
264	            4 => DynamicImage::ImageRgba8(
265	                ImageBuffer::from_vec(width, height, pixels).expect("Failed to create image"),
266	            ),
267	            _ => unreachable!("Already validated channel count above"),
268	        };
269	
270	        // Encode to bytes
271	        let mut bytes = Vec::new();
272	        dynamic_image
273	            .write_to(&mut Cursor::new(&mut bytes), format)
274	            .expect("Failed to encode test image");
275	        bytes
276	    }
