424	    fn test_with_runtime_preserves_server_config() {
425	        let server_limits = ImageDecoderLimits {
426	            max_image_width: Some(100),
427	            max_image_height: Some(100),
428	            max_alloc: Some(1024),
429	        };
430	        let server_config = ImageDecoder {
431	            limits: server_limits.clone(),
432	            ..Default::default()
433	        }
434	        .with_libjpeg_for_benchmark(false);
435	
436	        // Runtime config tries to override limits (should be ignored)
437	        let runtime_limits = ImageDecoderLimits {
438	            max_image_width: Some(9999),
439	            max_image_height: Some(9999),
440	            max_alloc: Some(999999),
441	        };
442	        let runtime_config = ImageDecoder {
443	            limits: runtime_limits,
444	            ..Default::default()
445	        }
446	        .with_libjpeg_for_benchmark(true);
447	
448	        let merged = server_config.with_runtime(Some(&runtime_config));
449	
450	        // Check that server limits are preserved
451	        assert_eq!(merged.limits.max_image_width, Some(100));
452	        assert_eq!(merged.limits.max_image_height, Some(100));
453	        assert_eq!(merged.limits.max_alloc, Some(1024));
454	        assert!(!merged.enable_libjpeg);
