1	// SPDX-FileCopyrightText: Copyright (c) 2024-2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
2	// SPDX-License-Identifier: Apache-2.0
3	
4	//! Runtime bindings for libjpeg-turbo's TurboJPEG decode API.
5	//!
6	//! The shared library is loaded with `dlopen` instead of linked at build time so
7	//! Dynamo keeps working in images that do not install libturbojpeg. JPEG inputs
8	//! use this fast path by default and fall back to the pure-Rust `image` decoder
9	//! when the library is unavailable.
10	
11	#![allow(unsafe_code)]
12	
13	use std::{
14	    os::raw::{c_int, c_uchar, c_ulong, c_void},
15	    ptr::NonNull,
16	    sync::OnceLock,
17	};
18	
19	use anyhow::{Result, bail};
20	use libloading::{Library, Symbol};
21	
22	type TjHandle = *mut c_void;
23	const TJCS_GRAY: c_int = 2;
24	const TJCS_CMYK: c_int = 3;
25	const TJCS_YCCK: c_int = 4;
26	const TJPF_RGB: c_int = 0;
27	const TJPF_GRAY: c_int = 6;
28	const TJFLAG_LIMITSCANS: c_int = 32_768;
29	
30	type TjInitDecompress = unsafe extern "C" fn() -> TjHandle;
31	type TjDecompressHeader3 = unsafe extern "C" fn(
32	    TjHandle,
33	    *const c_uchar,
34	    c_ulong,
35	    *mut c_int,
36	    *mut c_int,
37	    *mut c_int,
38	    *mut c_int,
39	) -> c_int;
40	type TjDecompress2 = unsafe extern "C" fn(
41	    TjHandle,
42	    *const c_uchar,
43	    c_ulong,
44	    *mut c_uchar,
45	    c_int,
46	    c_int,
47	    c_int,
48	    c_int,
49	    c_int,
50	) -> c_int;
51	type TjDestroy = unsafe extern "C" fn(TjHandle) -> c_int;
52	
53	struct TurboJpeg {
54	    _lib: Library,
55	    init: TjInitDecompress,
56	    header: TjDecompressHeader3,
57	    decompress: TjDecompress2,
58	    destroy: TjDestroy,
59	}
60	
61	struct TurboJpegHandle<'a> {
62	    api: &'a TurboJpeg,
63	    handle: NonNull<c_void>,
64	}
65	
66	impl<'a> TurboJpegHandle<'a> {
67	    fn new(api: &'a TurboJpeg) -> Option<Self> {
68	        // SAFETY: `init` is the resolved tjInitDecompress symbol.
69	        let handle = NonNull::new(unsafe { (api.init)() })?;
70	        Some(Self { api, handle })
71	    }
72	
73	    fn as_ptr(&self) -> TjHandle {
74	        self.handle.as_ptr()
75	    }
76	}
77	
78	impl Drop for TurboJpegHandle<'_> {
79	    fn drop(&mut self) {
80	        // SAFETY: This guard uniquely owns the non-null handle, and borrowing
81	        // `api` keeps the library and tjDestroy symbol alive through this call.
82	        unsafe {
83	            (self.api.destroy)(self.handle.as_ptr());
84	        }
85	    }
86	}
87	
88	#[derive(Debug)]
89	pub(crate) struct DecodedJpeg {
90	    pub(crate) width: u32,
91	    pub(crate) height: u32,
92	    pub(crate) channels: usize,
93	    pub(crate) data: Vec<u8>,
94	}
95	
96	fn load_turbojpeg() -> Option<TurboJpeg> {
97	    const CANDIDATES: &[&str] = &[
98	        "libturbojpeg.so.0",
99	        "libturbojpeg.so",
100	        "libturbojpeg.0.dylib",
101	        "libturbojpeg.dylib",
102	    ];
103	
104	    // SAFETY: Load the documented TurboJPEG shared library by soname and only
105	    // resolve the four symbols below.
106	    let lib = CANDIDATES
107	        .iter()
108	        .find_map(|name| unsafe { Library::new(name) }.ok())?;
109	
110	    // SAFETY: The symbol signatures match the TurboJPEG C API. We copy bare
111	    // function pointers while keeping `lib` alive in TurboJpeg.
112	    let (init, header, decompress, destroy) = unsafe {
113	        let init: Symbol<TjInitDecompress> = lib.get(b"tjInitDecompress\0").ok()?;
114	        let header: Symbol<TjDecompressHeader3> = lib.get(b"tjDecompressHeader3\0").ok()?;
115	        let decompress: Symbol<TjDecompress2> = lib.get(b"tjDecompress2\0").ok()?;
116	        let destroy: Symbol<TjDestroy> = lib.get(b"tjDestroy\0").ok()?;
117	        (*init, *header, *decompress, *destroy)
118	    };
119	
120	    Some(TurboJpeg {
121	        _lib: lib,
122	        init,
123	        header,
124	        decompress,
125	        destroy,
126	    })
127	}
128	
129	fn turbojpeg() -> Option<&'static TurboJpeg> {
130	    static TJ: OnceLock<Option<TurboJpeg>> = OnceLock::new();
131	    TJ.get_or_init(load_turbojpeg).as_ref()
132	}
133	
134	pub(crate) fn available() -> bool {
135	    turbojpeg().is_some()
136	}
137	
138	pub(crate) fn is_jpeg(bytes: &[u8]) -> bool {
139	    bytes.len() >= 3 && bytes[0] == 0xFF && bytes[1] == 0xD8 && bytes[2] == 0xFF
140	}
141	
142	/// Decode JPEG bytes to HWC UINT8 using libjpeg-turbo defaults.
143	///
144	/// Returns `Ok(None)` for non-JPEG inputs, missing libturbojpeg, or decoder
145	/// failures that the caller should pass to the standard `image` fallback.
146	/// Configured resource limits return `Err` because falling back should not
147	/// bypass them.
148	pub(crate) fn decode_jpeg(
149	    bytes: &[u8],
150	    max_width: Option<u32>,
151	    max_height: Option<u32>,
152	    max_alloc: Option<u64>,
153	) -> Result<Option<DecodedJpeg>> {
154	    if !is_jpeg(bytes) {
155	        return Ok(None);
156	    }
157	    let Some(tj) = turbojpeg() else {
158	        return Ok(None);
159	    };
160	
161	    // SAFETY:
162	    // - TurboJpegHandle owns the non-null handle and destroys it on every exit.
163	    // - `bytes` is a valid immutable input buffer for the duration of each C call.
164	    // - `buf` reserves width * height * channels after checked arithmetic and
165	    //   configured limits; a successful decode initializes that full layout.
166	    unsafe {
167	        let Some(handle) = TurboJpegHandle::new(tj) else {
168	            return Ok(None);
169	        };
170	
171	        let (mut w, mut h, mut subsamp, mut colorspace) = (0_i32, 0_i32, 0_i32, 0_i32);
172	        let hdr = (tj.header)(
173	            handle.as_ptr(),
174	            bytes.as_ptr(),
175	            bytes.len() as c_ulong,
176	            &mut w,
177	            &mut h,
178	            &mut subsamp,
179	            &mut colorspace,
180	        );
181	        if hdr != 0 || w <= 0 || h <= 0 {
182	            return Ok(None);
183	        }
184	        // TurboJPEG cannot convert CMYK/YCCK JPEGs directly to TJPF_RGB.
185	        // Decline before allocating the RGB output so ImageReader handles them.
186	        if matches!(colorspace, TJCS_CMYK | TJCS_YCCK) {
187	            return Ok(None);
188	        }
189	
190	        let (width, height) = (w as u32, h as u32);
191	        if max_width.is_some_and(|limit| width > limit)
192	            || max_height.is_some_and(|limit| height > limit)
193	        {
194	            bail!("Image dimensions exceed configured limits: {width}x{height}");
195	        }
196	
197	        let (pixel_format, channels) = if colorspace == TJCS_GRAY {
198	            (TJPF_GRAY, 1_usize)
199	        } else {
200	            (TJPF_RGB, 3_usize)
201	        };
202	        let nbytes = match u64::from(width)
203	            .checked_mul(u64::from(height))
204	            .and_then(|p| p.checked_mul(channels as u64))
205	        {
206	            Some(n) => n,
207	            None => {
208	                bail!("Image allocation size overflow for dimensions: {width}x{height}");
209	            }
210	        };
211	        if let Some(limit) = max_alloc
212	            && nbytes > limit
213	        {
214	            bail!("Image allocation {nbytes} bytes exceeds configured limit {limit} bytes");
215	        }
216	
217	        let nbytes = match usize::try_from(nbytes) {
218	            Ok(n) => n,
219	            Err(_) => {
220	                bail!("Image allocation size does not fit in usize: {nbytes} bytes");
221	            }
222	        };
223	        let mut buf = Vec::new();
224	        if let Err(err) = buf.try_reserve_exact(nbytes) {
225	            bail!("Image allocation {nbytes} bytes could not be reserved: {err:?}");
226	        }
227	        let rc = (tj.decompress)(
228	            handle.as_ptr(),
229	            bytes.as_ptr(),
230	            bytes.len() as c_ulong,
231	            buf.as_mut_ptr(),
232	            w,
233	            0,
234	            h,
235	            pixel_format,
236	            TJFLAG_LIMITSCANS,
237	        );
238	        if rc != 0 {
239	            return Ok(None);
240	        }
241	        buf.set_len(nbytes);
242	
243	        Ok(Some(DecodedJpeg {
244	            width,
245	            height,
246	            channels,
247	            data: buf,
248	        }))
249	    }
250	}
